<div class="footer-contact"><div class="footer-heading"><?php echo bl_text(bl_field('footer_contact_heading', 'option')); ?></div><p><a href="tel:<?php echo esc_attr(preg_replace('/[^+0-9]/', '', (string) bl_field('phone', 'option'))); ?>"><?php echo bl_text(bl_field('phone', 'option')); ?></a></p><p><a href="mailto:<?php echo esc_attr(bl_field('email', 'option')); ?>"><?php echo bl_text(bl_field('email', 'option')); ?></a></p><?php foreach (bl_rows(bl_field('social_links', 'option')) as $link): ?><p><a href="<?php echo esc_url($link['url'] ?? ''); ?>" rel="noopener noreferrer"><?php echo bl_text($link['label'] ?? ''); ?></a></p><?php endforeach; ?></div>
